{
  "title": "Numeric rate/count tokens (per‑100 / per‑1000)",
  "explanation": "Both features detect numeric expressions used for rates and counts (e.g., “per 100”, “per 1000”, spelled-out “hundred”); the moderate Jaccard (0.36) shows substantial overlap. The Group feature additionally highlights smaller integers like “30” and the spelled word “hundred,” suggesting sensitivity to standalone small counts and written-out numbers. The Baseline feature weights the subtoken “000” more strongly, indicating it pays more attention to formatted large numbers (e.g., 100,000) produced by tokenization. Overall, both capture epidemiological/counting contexts but differ in granularity and formatting sensitivity.",
  "tags": ["numerical", "units", "tokenization", "epidemiology"]
}

{
  "title": "Star (*) token — exponentiation/multiplication in algebraic expressions",
  "explanation": "Both features activate on the '*' token in short algebra/math snippets, but with different emphases. Group feature 3069 predominantly fires on exponentiation and polynomial patterns (frequent '**' sequences like v**3, o**4) and expansion of higher-order terms. Baseline feature 871 also targets '*' occurrences but appears more tied to rearrangement/simplification contexts (multiplication by zero, coefficient-heavy arithmetic and form transformations). The Jaccard 0.439 shows moderate overlap: both detect operator-heavy algebra, while Group is more exponent-focused and Baseline more simplification/rearrangement-focused.",
  "tags": ["operator-token", "exponentiation", "algebraic-expansion"]
}

{
  "title": "Both features detect the adversative 'but'; group leans narrative, baseline is broader",
  "explanation": "Both Group-SAE 8304 and Baseline-SAE 9724 strongly activate on the token 'but' used as an adversative/coordinating conjunction (Jaccard 0.430). They pick out sentence-internal contrast markers, but the Group feature's top snippets skew toward narrative and emotive usages (character dialogue, personal regret, mitigation/positivizing after criticism), while the Baseline feature appears in a wider variety of registers including technical/procedural contexts and idiomatic conversational turns. Overall the functions overlap (marking contrast), with the Group variant showing a slight preference for narrative/emotional contexts.",
  "tags": ["coordinating-conjunction", "contrast", "register"]
}

{
  "title": "Named social platforms vs. generic discussion venues",
  "explanation": "The Group-SAE feature fires on specific social-network proper nouns (Twitter, Instagram, Reddit, 4chan), i.e., mentions of particular platforms, whereas the Baseline-SAE captures generic discussion-space vocabulary (forum, boards, thread, sections, HN). They overlap on platform references like Reddit, but the Group feature is more entity/platform-specific while the Baseline is a broader ‘discussion venue’ detector.",
  "tags": ["social-media", "forums", "named-entities", "discussion-structure"]
}

{
  "title": "Possessive-pronoun specialist vs. broader function-word feature",
  "explanation": "Group feature 2135 (layer 13) is tightly focused on possessive pronouns (his, our, their, my and capitalized variants), activating on token-level expressions of ownership/possession in short contexts. Baseline feature 16100 (layer 13) shows moderate overlap (Jaccard 0.459) but is less selective: it includes high-frequency function words like \"a\" and \"it\" alongside possessives, yielding a more diffuse, general-purpose signal.",
  "tags": ["possessive pronouns", "function words", "ownership", "pronouns"]
}

{
  "title": "Group: Czech subword/diacritic detector vs Baseline: short Slavic function tokens",
  "explanation": "The Group-SAE feature activates on subword fragments and Czech-specific characters (ř, č, ý) and pieces of morphological endings found in names/technical terms (e.g., -ický, -ný, pátrač). The Baseline-SAE feature instead lights up on very short, high-frequency function tokens (single-letter 'z' and 'pri') appearing in Slovak/Czech running text. The moderate Jaccard (0.561) reflects that both capture Slavic-language contexts, but the group feature is sensitive to orthographic/morphological subunits and diacritics while the baseline captures boundary-level/prepositional tokens.",
  "tags": ["subword-morphology", "diacritics", "Slavic-function-words"]
}

{
  "title": "Detects inline figure/table reference markup (' ](# ')",
  "explanation": "Both features activate on the punctuation sequence used for inline reference links (e.g., [Table 1 **](#** ...){ref-type=\"table\"} and [Fig X **](#** ...){ref-type=\"fig\"}). Group feature 9183 is biased toward table/supplement references and repeated Table patterns, while Baseline 2209 covers a broader set of figure references, domain-coded IDs (pcbi/pone) and small punctuation/formatting variants. The moderate Jaccard (0.452) reflects this overlap on the same markup token but different contextual specializations.",
  "tags": ["markup", "references", "figures-tables"]
}

{
  "title": "Period (.) token — file extensions, paths and diff/patch punctuation",
  "explanation": "Both features strongly activate on the single token '.' which appears as punctuation in code and text: file extensions (e.g., .php, .c, .ml), path fragments, and diff/patch markers. The Jaccard 0.481 shows substantial overlap. The Group feature examples concentrate on inline filenames and small code/path fragments, while the Baseline also captures broader diff headers and surrounding structural lines, so the baseline contexts are slightly more varied.",
  "tags": ["punctuation", "file-extensions", "code-context"]
}

